window.kbPageData["views/entry/k-fd8bf3a6c75a3668"] = {"key":"entry/k-fd8bf3a6c75a3668","state":{"route":"entry/k-fd8bf3a6c75a3668"},"node":{"id":"k-fd8bf3a6c75a3668","mode":"k","title":"相容析取的真假","type":"原理与机制","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":["相容析取为假时两个支命题均为假"],"qs":["国考 2025 副省级 行测#110"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"相容析取“P或Q”在至少一个支命题为真时为真，只有两个支命题都为假时才为假。","review":{"definition":"相容析取“P或Q”在至少一个支命题为真时为真，只有两个支命题都为假时才为假。","explanation":"甲、乙若都说假话，东面和南面就各有一人说真话，违反全桌只有一人说真话的条件。因此唯一说真话的人在甲、乙之中，丙的“我坐在西面或者北面”为假，西面和北面都可以排除。若丙坐东面，按顺时针顺序丁就坐南面，甲、乙的陈述会同时为真。故丙坐南面，甲坐北面，选A。","references":[],"evidence":"丙说假话意味着，丙不坐在西面也不坐在北面","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2025 副省级 行测#110":{"paper":"国考 2025 副省级 行测","n":110,"mod":"判断推理","src":["ffe12c35a46d4df574ec.pdf",21],"asrc":["ff0b352b44d417525086.pdf",35],"card":"e2bea642de269a9895cb8810","links":[{"id":"k-fd8bf3a6c75a3668","role":"解题依据","why":"用这一真值规则把丙的假陈述转化为两个可以排除的方位。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-fd8bf3a6c75a3668":[["国考 2025 副省级 行测#110"]]}};
